import React, { useState } from 'react';
import { Menu, Search, X } from 'lucide-react';

export default function Header() {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <header className="header" style={{ backgroundColor: '#e8f0f8' }}>
      <div className="header-container" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 24px', gap: '24px' }}>
        
        {/* Left Section - Search Box */}
        <div className="search-section" style={{ flex: 1, maxWidth: '400px' }}>
          <div className="search-box" style={{ display: 'flex', alignItems: 'center', backgroundColor: '#f3f4f6', borderRadius: '8px', padding: '10px 16px', gap: '8px' }}>
            <Search size={18} color="#9ca3af" />
            <input 
              type="text" 
              placeholder="Search courses..." 
              style={{ border: 'none', backgroundColor: 'transparent', outline: 'none', fontSize: '14px', width: '100%' }}
            />
          </div>
        </div>

        {/* Right Section - Auth Buttons */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <button 
            className="sign-in-btn" 
            style={{ 
              background: 'none', 
              border: 'none', 
              fontSize: '14px', 
              fontWeight: '500', 
              cursor: 'pointer',
              color: '#4b5563',
              padding: '8px 16px'
            }}
          >
            Sign In
          </button>
          <button 
            className="log-in-btn"
            style={{ 
              backgroundColor: '#4F46E5', 
              color: 'white', 
              border: 'none', 
              borderRadius: '8px', 
              padding: '10px 24px',
              fontSize: '14px',
              fontWeight: '600',
              cursor: 'pointer',
              transition: 'background-color 0.2s'
            }}
            onMouseEnter={(e) => e.target.style.backgroundColor = '#4338CA'}
            onMouseLeave={(e) => e.target.style.backgroundColor = '#4F46E5'}
          >
            Log In
          </button>
        </div>

        {/* Mobile Menu Button */}
        <button 
          className="menu-button" 
          onClick={toggleMobileMenu}
          style={{ display: 'none', background: 'none', border: 'none', cursor: 'pointer' }}
        >
          {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>
    </header>
  );
}
